func _run_tests() -> void:
	var file := FileAccess.open("res://adventure.json", FileAccess.READ)
	if not check("file_open", file != null, "Il file res://adventure.json deve esistere e potersi aprire in lettura"):
		return
	var text := file.get_as_text()
	file.close()
	if not check("not_empty", not text.strip_edges().is_empty(), "Il file adventure.json non deve essere vuoto"):
		return
	var json = JSON.parse_string(text)
	if not check("json_valid", json is Dictionary, "Il file adventure.json deve contenere un oggetto JSON valido (dizionario con graffe)"):
		return
	var data: Dictionary = json
	check("has_title", data.get("title") is String and not (data["title"] as String).strip_edges().is_empty(), "Il file deve contenere la chiave 'title' con un testo non vuoto")
	var start_room = data.get("start_room")
	if not check("has_start_room", start_room is String and not (start_room as String).strip_edges().is_empty(), "Il file deve contenere la chiave 'start_room' con l'ID della stanza iniziale"):
		return
	var rooms = data.get("rooms")
	if not check("has_rooms", rooms is Dictionary, "Il file deve contenere la chiave 'rooms' di tipo Dictionary"):
		return
	var rooms_dict: Dictionary = rooms
	if not check("room_count", rooms_dict.size() >= 4, "L'avventura deve contenere almeno 4 stanze (trovate %d)" % rooms_dict.size()):
		return
	if not check("start_room_exists", rooms_dict.has(start_room), "La stanza iniziale '%s' specificata in start_room deve esistere dentro rooms" % str(start_room)):
		return

	var total_items := 0
	var all_exits_valid := true
	var bad_exit_msg := ""

	for room_id in rooms_dict:
		var room = rooms_dict[room_id]
		if not (room is Dictionary):
			check("room_dict_" + str(room_id), false, "La stanza '%s' deve essere un Dictionary" % str(room_id))
			return
		var r: Dictionary = room
		if not check("room_name_" + str(room_id), r.get("name") is String and not (r["name"] as String).strip_edges().is_empty(), "La stanza '%s' deve avere un campo 'name' di tipo String non vuoto" % str(room_id)):
			return
		if not check("room_desc_" + str(room_id), r.get("description") is String and not (r["description"] as String).strip_edges().is_empty(), "La stanza '%s' deve avere un campo 'description' di tipo String non vuoto" % str(room_id)):
			return
		if not check("room_exits_" + str(room_id), r.get("exits") is Dictionary, "La stanza '%s' deve avere un campo 'exits' di tipo Dictionary" % str(room_id)):
			return
		if not check("room_items_" + str(room_id), r.get("items") is Array, "La stanza '%s' deve avere un campo 'items' di tipo Array" % str(room_id)):
			return

		var items_arr: Array = r["items"]
		total_items += items_arr.size()

		var exits_dict: Dictionary = r["exits"]
		for dir in exits_dict:
			var target = exits_dict[dir]
			if not (target is String) or not rooms_dict.has(target):
				all_exits_valid = false
				bad_exit_msg = "L'uscita '%s' della stanza '%s' punta a '%s', che non esiste in rooms" % [str(dir), str(room_id), str(target)]
				break
		if not all_exits_valid:
			break

	if not check("exits_valid", all_exits_valid, bad_exit_msg if not bad_exit_msg.is_empty() else "Tutte le uscite devono puntare a stanze esistenti"):
		return

	check("total_items", total_items >= 2, "L'avventura deve contenere almeno 2 oggetti in totale tra le varie stanze (trovati %d)" % total_items)

	var visited := {}
	var queue: Array[String] = [start_room as String]
	while not queue.is_empty():
		var curr: String = queue.pop_front()
		if visited.has(curr):
			continue
		visited[curr] = true
		var r_data: Dictionary = rooms_dict[curr]
		var exits: Dictionary = r_data["exits"]
		for dir in exits:
			var target_id: String = exits[dir]
			if not visited.has(target_id):
				queue.append(target_id)

	var unreachable: Array[String] = []
	for room_id in rooms_dict:
		if not visited.has(room_id):
			unreachable.append(str(room_id))

	check("all_reachable", unreachable.is_empty(), "Tutte le stanze devono essere raggiungibili dalla stanza iniziale seguendo le uscite. Stanze isolate: %s" % str(unreachable))
